<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── element spec ───────────────────────────────────────────────────────────
// upper nappe   → ConeGeometry(1.2,2.2,64,1,true) rot X π, MeshBasic #CBDDF2 op .55 DoubleSide
// lower nappe   → ConeGeometry(1.2,2.2,64,1,true) translated -1.1, same material
// top rim       → Line full circle r=1.2 at y=+2.2, #2B4C86 solid
// bottom rim    → 2 × Line half circles at y=-2.2 : near half solid, far half LineDashedMaterial
// silhouette    → 4 × Line apex(0,0,0) → (0,±2.2,±1.2) forming the X, #2B4C86
// cutting plane → PlaneGeometry(3,3) MeshBasic #7FA6DC op .14 DoubleSide (toggle)
// conic curve   → TubeGeometry over analytic conic points, #E0342B r=.022
// arrowheads    → ConeGeometry(.055,.15) #E0342B at open branch ends
// flat curve    → TubeGeometry of same conic re-drawn in world XY plane, #E0342B
// labels        → addLabel: slice title (top), curve name (bottom)

const R = 1.2, H = 2.2, K = R / H;
const NAVY = 0x2B4C86, PALE = 0xCBDDF2, RED = 0xE0342B;
const P0Y = 1.0;
const BETA_PAR = THREE.MathUtils.radToDeg(Math.atan(1 / K)); // ≈ 61.39°

/* ── groups ─────────────────────────────────────────────────────────────── */
const coneGroup = new THREE.Group();   // cone + 3D curve + plane
const flatGroup = new THREE.Group();   // isolated planar curve
const azGroup = new THREE.Group();     // parts that track camera azimuth
const curveGroup = new THREE.Group();  // red 3D conic
coneGroup.add(azGroup, curveGroup);
scene.add(coneGroup);

/* ── nappes ─────────────────────────────────────────────────────────────── */
const coneMat = new THREE.MeshBasicMaterial({
  color: PALE, transparent: true, opacity: 0.55,
  side: THREE.DoubleSide, depthWrite: false
});
const upG = new THREE.ConeGeometry(R, H, 64, 1, true); upG.rotateX(Math.PI); upG.translate(0, H / 2, 0);
const dnG = new THREE.ConeGeometry(R, H, 64, 1, true); dnG.translate(0, -H / 2, 0);
const upMesh = new THREE.Mesh(upG, coneMat);
const dnMesh = new THREE.Mesh(dnG, coneMat);
coneGroup.add(upMesh, dnMesh);
registerInteractive(upMesh, {
  title: 'Upper nappe', tooltip: 'Upper nappe of the double cone',
  body: 'Rim radius 1.2, height 2.2, so the half-angle from the axis is α = atan(1.2/2.2) ≈ 28.6°. Every conic is the trace of a plane on this surface.'
});
registerInteractive(dnMesh, {
  title: 'Lower nappe', tooltip: 'Lower nappe',
  body: 'The mirrored cone sharing the apex. A cutting plane steeper than 90° − α ≈ 61.4° reaches this nappe too, which is why the hyperbola has two branches.'
});

/* ── rims / silhouette ──────────────────────────────────────────────────── */
function arcPts(y, a0, a1, n) {
  const p = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * i / n;
    p.push(new THREE.Vector3(R * Math.cos(t), y, R * Math.sin(t)));
  }
  return p;
}
const navyMat = new THREE.LineBasicMaterial({ color: NAVY });
const dashMat = new THREE.LineDashedMaterial({ color: NAVY, dashSize: 0.11, gapSize: 0.09 });

const topRim = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(arcPts(H, 0, Math.PI * 2, 96)), navyMat);
coneGroup.add(topRim);

const nearHalf = new THREE.Line(new THREE.BufferGeometry().setFromPoints(arcPts(-H, -Math.PI / 2, Math.PI / 2, 48)), navyMat);
const farGeo = new THREE.BufferGeometry().setFromPoints(arcPts(-H, Math.PI / 2, Math.PI * 1.5, 48));
const farHalf = new THREE.Line(farGeo, dashMat); farHalf.computeLineDistances();
azGroup.add(nearHalf, farHalf);

[[H, R], [H, -R], [-H, R], [-H, -R]].forEach(([y, z]) => {
  azGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, y, z)]), navyMat));
});

/* ── cutting plane ──────────────────────────────────────────────────────── */
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(3, 3),
  new THREE.MeshBasicMaterial({ color: 0x7FA6DC, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false })
);
coneGroup.add(planeMesh);
registerInteractive(planeMesh, {
  title: 'Cutting plane', tooltip: 'The slicing plane',
  body: 'Tilt β is measured from horizontal. β = 0 → circle · 0 < β < 61.4° → ellipse · β = 61.4° (parallel to a slant line) → parabola · β > 61.4° → hyperbola.'
});

/* ── analytic conic ─────────────────────────────────────────────────────── */
// Plane through (0, 1, 0) with in-plane basis u = (0,−sinβ, cosβ), v = (1,0,0).
// Point = (b, P0Y − a·sinβ, a·cosβ). Cone: x² + z² = K²y²  ⇒  A a² + B a + C + b² = 0.
const PAR_EPS = 0.004;
function coeffs(beta) {
  const br = THREE.MathUtils.degToRad(beta), s = Math.sin(br), c = Math.cos(br);
  return { A: c * c - K * K * s * s, B: 2 * K * K * P0Y * s, C: -K * K * P0Y * P0Y, s, c };
}
function conicBranches(beta) {
  const { A, B, C, s } = coeffs(beta);
  const f = a => -(A * a * a + B * a + C);
  let aLo = -60, aHi = 60;
  if (s > 1e-6) { aLo = (P0Y - H) / s; aHi = (P0Y + H) / s; }
  const ivs = [];
  if (Math.abs(A) < PAR_EPS) {
    if (Math.abs(B) > 1e-9) {
      const r = -C / B;
      if (B > 0) ivs.push([aLo, r]); else ivs.push([r, aHi]);
    }
  } else {
    const D = B * B - 4 * A * C;
    if (D <= 0) { if (A < 0) ivs.push([aLo, aHi]); }
    else {
      const sq = Math.sqrt(D);
      let r1 = (-B - sq) / (2 * A), r2 = (-B + sq) / (2 * A);
      if (r1 > r2) { const t = r1; r1 = r2; r2 = t; }
      if (A > 0) ivs.push([r1, r2]);
      else { ivs.push([aLo, r1]); ivs.push([r2, aHi]); }
    }
  }
  const out = [];
  for (const iv of ivs) {
    const p = Math.max(iv[0], aLo), q = Math.min(iv[1], aHi);
    if (!(q - p > 1e-4)) continue;
    const n = 150, up = [], lo = [];
    for (let i = 0; i <= n; i++) {
      const a = p + (q - p) * i / n;
      const b = Math.sqrt(Math.max(0, f(a)));
      up.push([a, b]); lo.push([a, -b]);
    }
    const revLo = lo.slice().reverse();
    const openP = f(p) > 1e-4, openQ = f(q) > 1e-4;
    if (!openP && !openQ) out.push({ pts: up.concat(revLo.slice(1, -1)), closed: true });
    else if (openP && !openQ) out.push({ pts: lo.concat(up.slice().reverse().slice(1)), closed: false });
    else if (!openP && openQ) out.push({ pts: revLo.concat(up.slice(1)), closed: false });
    else { out.push({ pts: up, closed: false }); out.push({ pts: lo, closed: false }); }
  }
