}
function conicName(beta) {
  if (beta < 0.5) return 'Circle';
  if (Math.abs(beta - BETA_PAR) < 1.0) return 'Parabola';
  return beta < BETA_PAR ? 'Ellipse' : 'Hyperbola';
}
function sliceName(beta) {
  const n = conicName(beta);
  return n === 'Circle' ? 'Horizontal Slice' : n === 'Ellipse' ? 'Diagonal Slice'
    : n === 'Parabola' ? 'Vertical Slice' : 'Deep Vertical Slice';
