  const to3 = (a, b) => new THREE.Vector3(b, P0Y - a * s, a * c);
  for (const br of conicBranches(beta)) {
    const pts = br.pts.map(([a, b]) => to3(a, b));
    addTube(curveGroup, pts, br.closed);
    if (!br.closed && pts.length > 3) {
      addArrow(curveGroup, pts[0], pts[0].clone().sub(pts[2]));
      const L = pts.length - 1;
      addArrow(curveGroup, pts[L], pts[L].clone().sub(pts[L - 2]));
    }
  }
  if (curveGroup.children.length) {
    registerInteractive(curveGroup.children[0], {
      title: 'Intersection curve', tooltip: 'Where plane meets cone',
      body: 'Substituting the plane parameterisation into x² + z² = (r/h)²y² gives A a² + B a + C + b² = 0 — a genuine conic in the plane’s own coordinates.'
    });
