/* ── build the isolated planar curve ────────────────────────────────────── */
function buildFlatCurve(beta) {
  clearGroup(flatGroup);
  const brs = conicBranches(beta);
  if (!brs.length) return;
  const closedKind = brs.every(b => b.closed);
  let aSum = 0, aN = 0;
  for (const br of brs) for (const [a] of br.pts) { aSum += a; aN++; }
  const aC = aSum / aN;
  const map = ([a, b]) => closedKind ? [a - aC, b] : [b, -(a - aC)];
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  const mapped = brs.map(br => {
    const m = br.pts.map(map);
    for (const [x, y] of m) { minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y); }
    return { m, closed: br.closed };
