  btnFlat.classList.toggle('active', state.mode === 'flat');

  placePlane(b);
  planeMesh.visible = state.showPlane && state.mode === 'cone';
  buildConeCurve(b);
  buildFlatCurve(b);

  const cmp = Math.abs(b - BETA_PAR) < 1.0 ? '=' : (b < BETA_PAR ? '&lt;' : '&gt;');
