    + '<br>' + (name === 'Circle' ? 'Cut perpendicular to the axis.'
      : name === 'Ellipse' ? 'Plane less steep than the cone’s side — the cut closes.'
        : name === 'Parabola' ? 'Plane parallel to a slant line — the cut can never close.'
          : 'Plane steeper than the side — it meets <i>both</i> nappes.');

  if (state.mode === 'cone') {
    lblTitle.div.style.visibility = 'visible';
    lblTitle.div.innerHTML = sliceName(b);
    lblTitle.pos.set(0, 2.95, 0);
    lblName.div.innerHTML = name;
