const steps = [
  { t: 'Diagonal Slice → Ellipse', n: 'A plane tilted about 25° from horizontal cuts clean through the upper nappe only; the red intersection closes into a tilted oval. Switch to “Curve alone” to see the flattened ellipse of the bottom row.', b: 25, m: 'cone' },
