  state.mode = m;
  if (m === 'flat') { scene.remove(coneGroup); scene.add(flatGroup); }
  else { scene.remove(flatGroup); scene.add(coneGroup); }
  update(true);
}

/* ── controls wiring ────────────────────────────────────────────────────── */
slider.addEventListener('input', () => { tweenId++; state.beta = parseFloat(slider.value); update(false); });
btnCone.addEventListener('click', () => setMode('cone'));
btnFlat.addEventListener('click', () => setMode('flat'));
chkPlane.addEventListener('change', () => { state.showPlane = chkPlane.checked; update(false); });

let tweenId = 0;
function tweenBeta(target, ms, done) {
  const id = ++tweenId, from = state.beta, t0 = performance.now();
  (function step() {
    if (id !== tweenId) return;
    const t = Math.min(1, (performance.now() - t0) / ms);
    const e = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    state.beta = from + (target - from) * e;
    update(false);
    if (t < 1) requestAnimationFrame(step); else if (done) done();
  })();
}
const presets = { Ellipse: 25, Circle: 0, Hyperbola: 85, Parabola: 61 };
Object.entries(conicBtns).forEach(([k, el]) => el.addEventListener('click', () => tweenBeta(presets[k], 600)));

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'Diagonal Slice → Ellipse', n: 'A plane tilted about 25° from horizontal cuts clean through the upper nappe only; the red intersection closes into a tilted oval. Switch to “Curve alone” to see the flattened ellipse of the bottom row.', b: 25, m: 'cone' },
  { t: 'Horizontal Slice → Circle', n: 'Level the plane to 0°. The cut is perpendicular to the cone axis, so every point of the red curve is the same distance from the axis — a circle, the special ellipse.', b: 0, m: 'cone' },
  { t: 'Vertical Slice → Parabola', n: 'At 61° the plane is exactly parallel to a slant line of the cone. The curve can no longer close: a single open red arc runs through one nappe — a parabola.', b: 61, m: 'cone' },
  { t: 'Deep Vertical Slice → Hyperbola', n: 'Past 61° — here 85°, nearly vertical — the plane is steeper than the cone’s side and so meets both nappes, producing two opposing red branches: a hyperbola.', b: 85, m: 'cone' },
  { t: 'Flatten the cut', n: 'Toggle to “Curve alone”: the plane swings face-on and the red intersection becomes the named planar graph drawn in the bottom row of the figure.', b: 85, m: 'flat' }
];
let stepIdx = 0, playing = false;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(i, after) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.t;
  stepText.textContent = s.n;
  setMode(s.m);
  tweenBeta(s.b, 650, after);
}
document.getElementById('nextStep').addEventListener('click', () => { playing = false; goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { playing = false; goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  playing = !playing;
  document.getElementById('playDemo').textContent = playing ? '❚❚ Pause' : '▶ Play';
  if (playing) run();
});
function run() {
  if (!playing) return;
  goToStep(stepIdx + 1, () => setTimeout(() => { if (playing) run(); }, 1700));
}

/* ── azimuth tracking for dashed rim + silhouette ───────────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  const dx = camera.position.x - controls.target.x;
  const dz = camera.position.z - controls.target.z;
  if (dx * dx + dz * dz > 1e-8) azGroup.rotation.y = Math.atan2(-dz, dx);
})();

/* ── go ─────────────────────────────────────────────────────────────────── */
update(false);
frameCamera();
document.getElementById('btnReset').style.display = '';
stepTitle.textContent = '1/5  ' + steps[0].t;
stepText.textContent = steps[0].n;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

