// @FIGURE_CODE_BEGIN
// ── element spec (one line per element) ────────────────────────────────────
// upper nappe    → ConeGeometry(1.2,2.2,64,1,true) rotX π, MeshBasic #CBDDF2 op .55 DoubleSide
// lower nappe    → ConeGeometry(1.2,2.2,64,1,true) translated −1.1, same material
// top rim        → LineLoop full circle r=1.2 at y=+2.2, #2B4C86 solid
// bottom rim     → 2 × Line half circles at y=−2.2: near half solid, far half LineDashed
// silhouette     → 4 × Line apex(0,0,0) → (0,±2.2,±1.2) forming the X, #2B4C86
// cutting plane  → PlaneGeometry(2.8,2.8) MeshBasic #7FA6DC op .13 DoubleSide (toggle, single view)
// slice curve    → TubeGeometry over analytic conic points, #E0342B r=.015
// arrowheads     → ConeGeometry(.045,.13) #E0342B at open branch ends (top row only)
// flat inset     → TubeGeometry of same conic re-drawn in world XY plane below cone, r=.018
// labels         → addLabel: bold slice title (top, 21px), β caption, bold conic name (above inset, 20px)
// all-four view  → 4 panels at x = −6,−2,+2,+6, betas 25°,0°,85°,61.4° each with inset + 2 labels

const R = 1.2, H = 2.2, K = R / H;
const NAVY = 0x2B4C86, PALE = 0xCBDDF2, RED = 0xE0342B;
const BETA_PAR = THREE.MathUtils.radToDeg(Math.atan(1 / K));   // ≈ 61.39°
const FLAT_Y = -4.05;

/* ── shared materials / geometries ──────────────────────────────────────── */
const coneMat = new THREE.MeshBasicMaterial({ color: PALE, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false });
const navyMat = new THREE.LineBasicMaterial({ color: NAVY });
const dashMat = new THREE.LineDashedMaterial({ color: NAVY, dashSize: 0.11, gapSize: 0.09 });
const redMat = new THREE.MeshBasicMaterial({ color: RED });
const planeMat = new THREE.MeshBasicMaterial({ color: 0x7FA6DC, transparent: true, opacity: 0.13, side: THREE.DoubleSide, depthWrite: false });

const upG = new THREE.ConeGeometry(R, H, 64, 1, true); upG.rotateX(Math.PI); upG.translate(0, H / 2, 0);
const dnG = new THREE.ConeGeometry(R, H, 64, 1, true); dnG.translate(0, -H / 2, 0);

function arcPts(y, a0, a1, n) {
  const p = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * i / n;
    p.push(new THREE.Vector3(R * Math.cos(t), y, R * Math.sin(t)));
  }
  return p;
}
const topRimGeo = new THREE.BufferGeometry().setFromPoints(arcPts(H, 0, Math.PI * 2, 96));
const nearGeo = new THREE.BufferGeometry().setFromPoints(arcPts(-H, -Math.PI / 2, Math.PI / 2, 48));
const farGeo = new THREE.BufferGeometry().setFromPoints(arcPts(-H, Math.PI / 2, Math.PI * 1.5, 48));
const planeGeo = new THREE.PlaneGeometry(2.8, 2.8);

/* ── analytic conic ─────────────────────────────────────────────────────────
   Plane: unit normal n = (0, cosβ, sinβ), foot point P = D(β)·n (distance D
   from the apex). In-plane basis u = (0,−sinβ, cosβ), v = (1,0,0):
        X(a,b) = (b, D cosβ − a sinβ, D sinβ + a cosβ)
   Substituting into the cone x² + z² = K²y² gives A a² + B a + C + b² = 0.  */
function planeD(beta) { return 1.45 + (0.62 - 1.45) * (beta / 90); }
function coeffs(beta) {
  const br = THREE.MathUtils.degToRad(beta), s = Math.sin(br), c = Math.cos(br), D = planeD(beta);
  return {
    A: c * c - K * K * s * s,
    B: 2 * D * s * c * (1 + K * K),
    C: D * D * (s * s - K * K * c * c),
    s, c, D
  };
}
function effBeta(b) { return Math.abs(b - BETA_PAR) < 0.6 ? BETA_PAR : b; }
function conicName(b) {
  b = effBeta(b);
  if (b < 0.5) return 'Circle';
  if (b === BETA_PAR) return 'Parabola';
  return b < BETA_PAR ? 'Ellipse' : 'Hyperbola';
}
function sliceName(b) {
  const n = conicName(b);
  return n === 'Circle' ? 'Horizontal Slice' : n === 'Ellipse' ? 'Diagonal Slice'
    : n === 'Parabola' ? 'Vertical Slice' : 'Deep Vertical Slice';
}

const PAR_EPS = 1e-6;
function branchesFor(beta) {
  const { A, B, C, s, c, D } = coeffs(beta);
  const f = a => -(A * a * a + B * a + C);
  let aLo = -60, aHi = 60;
  if (s > 1e-6) { aLo = (D * c - H) / s; aHi = (D * c + H) / s; }
  const ivs = [];
  if (Math.abs(A) < PAR_EPS) {
    if (Math.abs(B) > 1e-9) {
      const r = -C / B;
      if (B > 0) ivs.push([aLo, r]); else ivs.push([r, aHi]);
    }
  } else {
    const Dq = B * B - 4 * A * C;
    if (Dq <= 0) { if (A < 0) ivs.push([aLo, aHi]); }
    else {
      const sq = Math.sqrt(Dq);
      let r1 = (-B - sq) / (2 * A), r2 = (-B + sq) / (2 * A);
      if (r1 > r2) { const t = r1; r1 = r2; r2 = t; }
      if (A > 0) ivs.push([r1, r2]);
      else { ivs.push([aLo, r1]); ivs.push([r2, aHi]); }
    }
  }
  const out = [];
  for (const iv of ivs) {
    const p = Math.max(iv[0], aLo), q = Math.min(iv[1], aHi);
    if (!(q - p > 1e-4)) continue;
    const n = 150, up = [], lo = [];
    for (let i = 0; i <= n; i++) {
      const a = p + (q - p) * i / n;
      const b = Math.sqrt(Math.max(0, f(a)));
      up.push([a, b]); lo.push([a, -b]);
    }
    const revLo = lo.slice().reverse();
    const openP = f(p) > 1e-4, openQ = f(q) > 1e-4;
    if (!openP && !openQ) out.push({ pts: up.concat(revLo.slice(1, -1)), closed: true });
    else if (openP && !openQ) out.push({ pts: lo.concat(up.slice().reverse().slice(1)), closed: false });
    else if (!openP && openQ) out.push({ pts: revLo.concat(up.slice(1)), closed: false });
    else { out.push({ pts: up, closed: false }); out.push({ pts: lo, closed: false }); }
  }
  return out;
}

/* ── drawing helpers ────────────────────────────────────────────────────── */
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i]; g.remove(o); o.geometry?.dispose?.();
  }
}
function addTube(g, pts3, closed, rad) {
  const clean = [];
  for (const p of pts3) if (!clean.length || clean[clean.length - 1].distanceTo(p) > 1e-5) clean.push(p);
  if (clean.length < 4) return;
  const curve = new THREE.CatmullRomCurve3(clean, closed, 'centripetal');
  const geo = new THREE.TubeGeometry(curve, Math.min(260, clean.length * 2), rad, 7, closed);
  g.add(new THREE.Mesh(geo, redMat));
}
function addArrow(g, tip, dir) {
  const dd = dir.clone().normalize();
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.13, 12), redMat);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
  m.position.copy(tip).addScaledVector(dd, 0.055);
  g.add(m);
}

/* ── panel factory (one double cone + its slice + its flattened inset) ──── */
const azGroups = [];
function makePanel(xOffset) {
  const g = new THREE.Group(); g.position.x = xOffset;
  const up = new THREE.Mesh(upG, coneMat), dn = new THREE.Mesh(dnG, coneMat);
  g.add(up, dn);
  registerInteractive(up, {
    title: 'Upper nappe', tooltip: 'Upper nappe of the double cone',
    body: 'Rim radius 1.2, height 2.2, so the half-angle from the axis is α = atan(1.2/2.2) ≈ 28.6°. Every conic section is the trace a flat plane leaves on this surface.'
  });
  registerInteractive(dn, {
    title: 'Lower nappe', tooltip: 'Lower nappe',
    body: 'The mirrored cone sharing the apex. A plane steeper than 90° − α ≈ 61.4° reaches this nappe as well — that is exactly why a hyperbola has two branches.'
  });

  const az = new THREE.Group(); g.add(az); azGroups.push(az);
  g.add(new THREE.LineLoop(topRimGeo, navyMat));
  az.add(new THREE.Line(nearGeo, navyMat));
  const fh = new THREE.Line(farGeo, dashMat); fh.computeLineDistances(); az.add(fh);
  [[H, R], [H, -R], [-H, R], [-H, -R]].forEach(([y, z]) => {
    az.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, y, z)]), navyMat));
  });

  const plane = new THREE.Mesh(planeGeo, planeMat); g.add(plane);
  registerInteractive(plane, {
    title: 'Cutting plane', tooltip: 'The slicing plane',
    body: 'Its tilt β is measured from horizontal. β = 0 → circle · 0 < β < 61.4° → ellipse · β = 61.4° (parallel to a slant line) → parabola · β > 61.4° → hyperbola.'
  });

  const curveG = new THREE.Group(); g.add(curveG);
  const flatG = new THREE.Group(); flatG.position.y = FLAT_Y; g.add(flatG);
  registerInteractive(curveG, {
    title: 'Intersection curve', tooltip: 'Where the plane meets the cone',
    body: 'Substituting the plane parameterisation into x² + z² = (r/h)²y² gives A a² + B a + C + b² = 0 — a genuine conic written in the plane’s own coordinates.'
  });
  registerInteractive(flatG, {
    title: 'The cut, laid flat', tooltip: 'Same curve seen face-on',
    body: 'This is the identical red curve viewed perpendicular to the cutting plane — the bottom row of the textbook figure, where the conic appears as its familiar planar graph.'
  });
  return { group: g, plane, curveG, flatG };
}

function buildCurve(panel, beta, tubeR) {
  clearGroup(panel.curveG);
  const { s, c, D } = coeffs(beta);
  const to3 = (a, b) => new THREE.Vector3(b, D * c - a * s, D * s + a * c);
  for (const br of branchesFor(beta)) {
    const pts = br.pts.map(p => to3(p[0], p[1]));
    addTube(panel.curveG, pts, br.closed, tubeR);
    if (!br.closed && pts.length > 3) {
      addArrow(panel.curveG, pts[0], pts[0].clone().sub(pts[2]));
      const L = pts.length - 1;
      addArrow(panel.curveG, pts[L], pts[L].clone().sub(pts[L - 2]));
    }
  }
}

function buildFlat(panel, beta, maxW, maxH, tubeR) {
  const g = panel.flatG;
  clearGroup(g);
  const brs = branchesFor(beta);
  if (!brs.length) return;
  const closedKind = brs.every(b => b.closed);
  let aSum = 0, aN = 0;
  for (const br of brs) for (const p of br.pts) { aSum += p[0]; aN++; }
  const aC = aSum / aN;
  const map = closedKind ? (p) => [p[0] - aC, p[1]] : (p) => [p[1], -(p[0] - aC)];
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  const mapped = brs.map(br => {
    const m = br.pts.map(map);
    for (const q of m) {
      minX = Math.min(minX, q[0]); maxX = Math.max(maxX, q[0]);
      minY = Math.min(minY, q[1]); maxY = Math.max(maxY, q[1]);
    }
    return { m, closed: br.closed };
  });
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  const w = Math.max(maxX - minX, 1e-3), h = Math.max(maxY - minY, 1e-3);
  const sc = Math.min(maxW / w, maxH / h, 2.4);
  for (const { m, closed } of mapped) {
    const pts = m.map(q => new THREE.Vector3((q[0] - cx) * sc, (q[1] - cy) * sc, 0));
    addTube(g, pts, closed, tubeR);
  }
}

function placePlane(panel, beta) {
  const { s, c, D } = coeffs(beta);
  const n = new THREE.Vector3(0, c, s);
  panel.plane.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), n);
  panel.plane.position.set(0, D * c, D * s);
}

/* ── roots: single view and the four-panel comparison ───────────────────── */
const singleRoot = new THREE.Group();
const quadRoot = new THREE.Group();
const single = makePanel(0);
singleRoot.add(single.group);
scene.add(singleRoot);

const QUAD = [
  { x: -6, beta: 25, title: 'Diagonal Slice' },
  { x: -2, beta: 0, title: 'Horizontal Slice' },
  { x: 2, beta: 85, title: 'Deep Vertical Slice' },
  { x: 6, beta: BETA_PAR, title: 'Vertical Slice' }
];
const quadLabels = [];
QUAD.forEach(q => {
  const p = makePanel(q.x);
  p.plane.visible = false;
  buildCurve(p, q.beta, 0.015);
  buildFlat(p, q.beta, 2.3, 1.35, 0.018);
  quadRoot.add(p.group);
  q.panel = p;
});

/* ── labels ─────────────────────────────────────────────────────────────── */
const lblTitle = addLabel('Diagonal Slice', new THREE.Vector3(0, 2.66, 0), { bold: true, fontSize: '22px' });
const lblCaption = addLabel('', new THREE.Vector3(0, 2.18, 0), { fontSize: '12.5px', color: '#444' });
const lblName = addLabel('Ellipse', new THREE.Vector3(0, -2.86, 0), { bold: true, fontSize: '21px' });

QUAD.forEach(q => {
  const t = addLabel(q.title, new THREE.Vector3(q.x, 2.6, 0), { bold: true, fontSize: '16px' });
  const n = addLabel(conicName(q.beta), new THREE.Vector3(q.x, -2.86, 0), { bold: true, fontSize: '16px' });
  quadLabels.push(t, n);
});
function setLblVis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── state + UI refs ────────────────────────────────────────────────────── */
const state = { beta: 25, mode: 'single', showPlane: true };
const slider = document.getElementById('planeAngle');
const angVal = document.getElementById('angVal');
const readout = document.getElementById('readout');
const chkPlane = document.getElementById('showPlane');
const btnOne = document.getElementById('modeOne');
const btnAll = document.getElementById('modeAll');
const conicBtns = {
  Ellipse: document.getElementById('cEll'), Circle: document.getElementById('cCir'),
  Hyperbola: document.getElementById('cHyp'), Parabola: document.getElementById('cPar')
};

function frameCamera() {
  if (state.mode === 'single') {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 12, heightFraction: 0.88 });
  } else {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 12, heightFraction: 0.95 });
  }
  controls.minPolarAngle = THREE.MathUtils.degToRad(20);
  controls.maxPolarAngle = THREE.MathUtils.degToRad(160);
}

function update(reframe) {
  const b = effBeta(state.beta);
  angVal.textContent = state.beta.toFixed(0);
  slider.value = String(Math.round(state.beta));
  const name = conicName(state.beta);
  Object.entries(conicBtns).forEach(([k, el]) => el.classList.toggle('active', k === name && state.mode === 'single'));
  btnOne.classList.toggle('active', state.mode === 'single');
  btnAll.classList.toggle('active', state.mode === 'quad');

  placePlane(single, b);
  single.plane.visible = state.showPlane && state.mode === 'single';
  buildCurve(single, b, 0.015);
  buildFlat(single, b, 2.6, 1.5, 0.018);

  const cmp = (name === 'Parabola') ? '=' : (b < BETA_PAR ? '&lt;' : '&gt;');
  readout.innerHTML = '&beta; = <b>' + state.beta.toFixed(0) + '&deg;</b> ' + cmp
    + ' 90&deg; &minus; &alpha; = 61.4&deg; &rarr; <b style="color:#c0271f">' + name + '</b><br>'
    + (name === 'Circle' ? 'Cut perpendicular to the axis — every point of the cut is the same distance from it.'
      : name === 'Ellipse' ? 'Plane less steep than the cone’s side, so the cut closes into an oval.'
        : name === 'Parabola' ? 'Plane exactly parallel to a slant line — the cut can never close.'
          : 'Plane steeper than the side, so it meets <i>both</i> nappes: two branches.');

  lblTitle.div.innerHTML = sliceName(state.beta);
  lblName.div.innerHTML = name;
  lblCaption.div.innerHTML = 'cut at &beta; = ' + state.beta.toFixed(0) + '&deg; &nbsp;&rarr;&nbsp; ' + name;
  if (reframe) frameCamera();
}

function applyLabelVisibility() {
  const one = state.mode === 'single';
  setLblVis(lblTitle, one); setLblVis(lblCaption, one); setLblVis(lblName, one);
  quadLabels.forEach(l => setLblVis(l, !one));
}

function setMode(m) {
  if (state.mode === m) return;
  state.mode = m;
  if (m === 'quad') { scene.remove(singleRoot); scene.add(quadRoot); }
  else { scene.remove(quadRoot); scene.add(singleRoot); }
  applyLabelVisibility();
  update(true);
}

/* ── controls wiring ────────────────────────────────────────────────────── */
let tweenId = 0;
function tweenBeta(target, ms, done) {
  const id = ++tweenId, from = state.beta, t0 = performance.now();
  (function step() {
    if (id !== tweenId) return;
    const t = Math.min(1, (performance.now() - t0) / ms);
    const e = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    state.beta = from + (target - from) * e;
    update(false);
    if (t < 1) requestAnimationFrame(step); else if (done) done();
  })();
}

