    body: 'This is the identical red curve viewed perpendicular to the cutting plane — the bottom row of the textbook figure, where the conic appears as its familiar planar graph.'
  });
  return { group: g, plane, curveG, flatG };
}

function buildCurve(panel, beta, tubeR) {
  clearGroup(panel.curveG);
  const { s, c, D } = coeffs(beta);
  const to3 = (a, b) => new THREE.Vector3(b, D * c - a * s, D * s + a * c);
  for (const br of branchesFor(beta)) {
    const pts = br.pts.map(p => to3(p[0], p[1]));
    addTube(panel.curveG, pts, br.closed, tubeR);
    if (!br.closed && pts.length > 3) {
      addArrow(panel.curveG, pts[0], pts[0].clone().sub(pts[2]));
      const L = pts.length - 1;
      addArrow(panel.curveG, pts[L], pts[L].clone().sub(pts[L - 2]));
    }
  }
}

function buildFlat(panel, beta, maxW, maxH, tubeR) {
  const g = panel.flatG;
  clearGroup(g);
  const brs = branchesFor(beta);
  if (!brs.length) return;
  const closedKind = brs.every(b => b.closed);
  let aSum = 0, aN = 0;
  for (const br of brs) for (const p of br.pts) { aSum += p[0]; aN++; }
  const aC = aSum / aN;
  const map = closedKind ? (p) => [p[0] - aC, p[1]] : (p) => [p[1], -(p[0] - aC)];
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  const mapped = brs.map(br => {
    const m = br.pts.map(map);
    for (const q of m) {
      minX = Math.min(minX, q[0]); maxX = Math.max(maxX, q[0]);
      minY = Math.min(minY, q[1]); maxY = Math.max(maxY, q[1]);
    }
    return { m, closed: br.closed };
  });
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  const w = Math.max(maxX - minX, 1e-3), h = Math.max(maxY - minY, 1e-3);
  const sc = Math.min(maxW / w, maxH / h, 2.4);
  for (const { m, closed } of mapped) {
    const pts = m.map(q => new THREE.Vector3((q[0] - cx) * sc, (q[1] - cy) * sc, 0));
    addTube(g, pts, closed, tubeR);
  }
}

function placePlane(panel, beta) {
  const { s, c, D } = coeffs(beta);
  const n = new THREE.Vector3(0, c, s);
  panel.plane.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), n);
  panel.plane.position.set(0, D * c, D * s);
}

/* ── roots: single view and the four-panel comparison ───────────────────── */
const singleRoot = new THREE.Group();
const quadRoot = new THREE.Group();
const single = makePanel(0);
singleRoot.add(single.group);
scene.add(singleRoot);

const QUAD = [
  { x: -6, beta: 25, title: 'Diagonal Slice' },
  { x: -2, beta: 0, title: 'Horizontal Slice' },
  { x: 2, beta: 85, title: 'Deep Vertical Slice' },
  { x: 6, beta: BETA_PAR, title: 'Vertical Slice' }
];
const quadLabels = [];
QUAD.forEach(q => {
  const p = makePanel(q.x);
  p.plane.visible = false;
  buildCurve(p, q.beta, 0.015);
  buildFlat(p, q.beta, 2.3, 1.35, 0.018);
  quadRoot.add(p.group);
  q.panel = p;
});

/* ── labels ─────────────────────────────────────────────────────────────── */
const lblTitle = addLabel('Diagonal Slice', new THREE.Vector3(0, 2.66, 0), { bold: true, fontSize: '22px' });
const lblCaption = addLabel('', new THREE.Vector3(0, 2.18, 0), { fontSize: '12.5px', color: '#444' });
const lblName = addLabel('Ellipse', new THREE.Vector3(0, -2.86, 0), { bold: true, fontSize: '21px' });

QUAD.forEach(q => {
  const t = addLabel(q.title, new THREE.Vector3(q.x, 2.6, 0), { bold: true, fontSize: '16px' });
  const n = addLabel(conicName(q.beta), new THREE.Vector3(q.x, -2.86, 0), { bold: true, fontSize: '16px' });
  quadLabels.push(t, n);
});
function setLblVis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── state + UI refs ────────────────────────────────────────────────────── */
const state = { beta: 25, mode: 'single', showPlane: true };
const slider = document.getElementById('planeAngle');
const angVal = document.getElementById('angVal');
const readout = document.getElementById('readout');
const chkPlane = document.getElementById('showPlane');
const btnOne = document.getElementById('modeOne');
const btnAll = document.getElementById('modeAll');
const conicBtns = {
  Ellipse: document.getElementById('cEll'), Circle: document.getElementById('cCir'),
  Hyperbola: document.getElementById('cHyp'), Parabola: document.getElementById('cPar')
};

function frameCamera() {
  if (state.mode === 'single') {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 12, heightFraction: 0.88 });
  } else {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 12, heightFraction: 0.95 });
  }
  controls.minPolarAngle = THREE.MathUtils.degToRad(20);
  controls.maxPolarAngle = THREE.MathUtils.degToRad(160);
}

function update(reframe) {
  const b = effBeta(state.beta);
  angVal.textContent = state.beta.toFixed(0);
  slider.value = String(Math.round(state.beta));
  const name = conicName(state.beta);
  Object.entries(conicBtns).forEach(([k, el]) => el.classList.toggle('active', k === name && state.mode === 'single'));
  btnOne.classList.toggle('active', state.mode === 'single');
  btnAll.classList.toggle('active', state.mode === 'quad');

  placePlane(single, b);
  single.plane.visible = state.showPlane && state.mode === 'single';
  buildCurve(single, b, 0.015);
  buildFlat(single, b, 2.6, 1.5, 0.018);

  const cmp = (name === 'Parabola') ? '=' : (b < BETA_PAR ? '&lt;' : '&gt;');
  readout.innerHTML = '&beta; = <b>' + state.beta.toFixed(0) + '&deg;</b> ' + cmp
    + ' 90&deg; &minus; &alpha; = 61.4&deg; &rarr; <b style="color:#c0271f">' + name + '</b><br>'
    + (name === 'Circle' ? 'Cut perpendicular to the axis — every point of the cut is the same distance from it.'
      : name === 'Ellipse' ? 'Plane less steep than the cone’s side, so the cut closes into an oval.'
        : name === 'Parabola' ? 'Plane exactly parallel to a slant line — the cut can never close.'
          : 'Plane steeper than the side, so it meets <i>both</i> nappes: two branches.');

  lblTitle.div.innerHTML = sliceName(state.beta);
  lblName.div.innerHTML = name;
  lblCaption.div.innerHTML = 'cut at &beta; = ' + state.beta.toFixed(0) + '&deg; &nbsp;&rarr;&nbsp; ' + name;
  if (reframe) frameCamera();
}

function applyLabelVisibility() {
  const one = state.mode === 'single';
  setLblVis(lblTitle, one); setLblVis(lblCaption, one); setLblVis(lblName, one);
  quadLabels.forEach(l => setLblVis(l, !one));
}

function setMode(m) {
  if (state.mode === m) return;
  state.mode = m;
  if (m === 'quad') { scene.remove(singleRoot); scene.add(quadRoot); }
  else { scene.remove(quadRoot); scene.add(singleRoot); }
  applyLabelVisibility();
  update(true);
}

/* ── controls wiring ────────────────────────────────────────────────────── */
let tweenId = 0;
function tweenBeta(target, ms, done) {
  const id = ++tweenId, from = state.beta, t0 = performance.now();
  (function step() {
    if (id !== tweenId) return;
    const t = Math.min(1, (performance.now() - t0) / ms);
    const e = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    state.beta = from + (target - from) * e;
    update(false);
    if (t < 1) requestAnimationFrame(step); else if (done) done();
  })();
}

slider.addEventListener('input', () => {
  tweenId++;
  if (state.mode !== 'single') setMode('single');
  state.beta = parseFloat(slider.value);
  update(false);
});
btnOne.addEventListener('click', () => setMode('single'));
btnAll.addEventListener('click', () => { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; setMode('quad'); });
chkPlane.addEventListener('change', () => { state.showPlane = chkPlane.checked; update(false); });

const presets = { Ellipse: 25, Circle: 0, Hyperbola: 85, Parabola: BETA_PAR };
Object.entries(conicBtns).forEach(([k, el]) => el.addEventListener('click', () => {
  if (state.mode !== 'single') setMode('single');
  tweenBeta(presets[k], 600);
}));

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'Diagonal Slice → Ellipse', n: 'A plane tilted about 25° from horizontal cuts clean through the upper nappe only. The red intersection closes into a tilted oval; below the cone the same cut is drawn flat — an ellipse.', b: 25, m: 'single' },
  { t: 'Horizontal Slice → Circle', n: 'Level the plane to 0°. The cut is perpendicular to the axis, so every point of the red curve is the same distance from it: a circle, the special case of the ellipse.', b: 0, m: 'single' },
  { t: 'Vertical Slice → Parabola', n: 'At 61.4° the plane is exactly parallel to a slant line of the cone. The cut can no longer close — one open red arc runs out to the rim, and flattened it is a parabola.', b: BETA_PAR, m: 'single' },
  { t: 'Deep Vertical Slice → Hyperbola', n: 'Past 61.4° — here 85°, nearly vertical — the plane is steeper than the cone’s side, so it meets both nappes. Two opposing red branches appear: a hyperbola.', b: 85, m: 'single' },
  { t: 'All four side by side', n: 'The textbook layout: four double cones with their red slices on top and the matching flattened conics beneath. Compare how the tilt of the plane alone decides the curve.', b: 85, m: 'quad' }
];
let stepIdx = 0, playing = false;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(i, after) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.t;
  stepText.textContent = s.n;
  setMode(s.m);
  if (s.m === 'single') tweenBeta(s.b, 650, after);
  else { state.beta = s.b; update(false); if (after) setTimeout(after, 500); }
}
document.getElementById('nextStep').addEventListener('click', () => { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  playing = !playing;
  document.getElementById('playDemo').textContent = playing ? '❚❚ Pause' : '▶ Play';
  if (playing) run();
});
function run() {
  if (!playing) return;
  goToStep(stepIdx + 1, () => setTimeout(() => { if (playing) run(); }, 1900));
}

/* ── azimuth tracking for dashed rim + silhouette lines ─────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  const dx = camera.position.x - controls.target.x;
  const dz = camera.position.z - controls.target.z;
  if (dx * dx + dz * dz > 1e-8) {
    const r = Math.atan2(-dz, dx);
    for (const g of azGroups) g.rotation.y = r;
  }
})();

/* ── go ─────────────────────────────────────────────────────────────────── */
update(false);
applyLabelVisibility();
frameCamera();
document.getElementById('btnReset').style.display = '';
stepTitle.textContent = '1/5  ' + steps[0].t;
stepText.textContent = steps[0].n;
// @FIGURE_CODE_END

