/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'The figure: four slices', n: 'Four identical double cones, each cut by a plane at a different tilt. The red curve on top is the intersection; underneath, the same cut is drawn flat and true to shape — ellipse, circle, hyperbola, parabola.', b: 50, m: 'quad' },
  { t: 'Diagonal Slice → Ellipse', n: 'A plane tilted 50° from horizontal cuts clean through the upper nappe only. The red intersection closes into a tilted oval; flattened below the cone it is a distinctly elongated ellipse.', b: 50, m: 'single' },
  { t: 'Horizontal Slice → Circle', n: 'Level the plane to 0°. The cut is perpendicular to the axis, so every point of the red curve is the same distance from it: a circle — the special ellipse with equal axes.', b: 0, m: 'single' },
  { t: 'Vertical Slice → Parabola', n: 'At 61.4° the plane is exactly parallel to a slant line of the cone. The cut can no longer close — one open red arc runs out to the rim, and flattened it is a parabola.', b: BETA_PAR, m: 'single' },
  { t: 'Deep Vertical Slice → Hyperbola', n: 'Past 61.4° — here 85°, nearly vertical — the plane is steeper than the cone’s side, so it meets both nappes. Two opposing red branches appear: a hyperbola.', b: 85, m: 'single' },
  { t: 'Back to all four', n: 'Compare the row again: the tilt β of one flat plane, and nothing else, decides which conic you get.', b: 50, m: 'quad' }
];
let stepIdx = 0, playing = false;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(i, after) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.t;
  stepText.textContent = s.n;
  setMode(s.m);
  if (s.m === 'single') tweenBeta(s.b, 650, after);
  else { state.beta = s.b; update(false); if (after) setTimeout(after, 600); }
}
document.getElementById('nextStep').addEventListener('click', () => { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  // @FIGURE_CODE_BEGIN
// ── element spec (one line per element) ────────────────────────────────────
// upper nappe    → ConeGeometry(1.2,2.2,64,1,true) rotX π, MeshBasic #CBDDF2 op .55 DoubleSide
// lower nappe    → ConeGeometry(1.2,2.2,64,1,true) translated −1.1, same material
// top rim        → LineLoop full circle r=1.2 at y=+2.2, #2B4C86 solid
// bottom rim     → 2 × Line half circles at y=−2.2: near half solid, far half LineDashed
// silhouette     → 4 × Line apex(0,0,0) → (0,±2.2,±1.2) forming the X, #2B4C86
// cutting disc   → CircleGeometry(1,64) scaled to the cut + LineLoop rim, #7FA6DC op .12 (single view only)
// β annotation   → 2 × Line rays from the plane foot + arc Line + "β" label, grey (single view only)
// slice curve    → TubeGeometry over analytic conic points, #E0342B r=.016
// arrowheads     → ConeGeometry(.05,.14) #E0342B at open branch ends
// flat inset     → TubeGeometry of the same conic, TRUE aspect ratio, below the cone, r=.019
// labels         → addLabel: bold slice title above each cone, bold conic name above each inset
// all-four view  → 4 panels at x = −4.5,−1.5,+1.5,+4.5 with β = 50°,0°,85°,61.4° (parabola mirrored)

const R = 1.2, H = 2.2, K = R / H;
const NAVY = 0x2B4C86, PALE = 0xCBDDF2, RED = 0xE0342B;
const BETA_PAR = THREE.MathUtils.radToDeg(Math.atan(1 / K));   // ≈ 61.39°
const FLAT_Y = -4.0, NAME_Y = -2.95, TITLE_Y = 2.62;
const FIT_MARGIN = 0.85;

/* ── shared materials / geometries ──────────────────────────────────────── */
const coneMat = new THREE.MeshBasicMaterial({ color: PALE, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false });
const navyMat = new THREE.LineBasicMaterial({ color: NAVY });
const dashMat = new THREE.LineDashedMaterial({ color: NAVY, dashSize: 0.11, gapSize: 0.09 });
const redMat = new THREE.MeshBasicMaterial({ color: RED });
const planeMat = new THREE.MeshBasicMaterial({ color: 0x7FA6DC, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false });
const ringMat = new THREE.LineBasicMaterial({ color: 0x6F97CC, transparent: true, opacity: 0.75 });
const thinMat = new THREE.LineBasicMaterial({ color: 0x777777 });

const upG = new THREE.ConeGeometry(R, H, 64, 1, true); upG.rotateX(Math.PI); upG.translate(0, H / 2, 0);
const dnG = new THREE.ConeGeometry(R, H, 64, 1, true); dnG.translate(0, -H / 2, 0);

function arcPts(y, a0, a1, n) {
  const p = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * i / n;
    p.push(new THREE.Vector3(R * Math.cos(t), y, R * Math.sin(t)));
  }
  return p;
}
const topRimGeo = new THREE.BufferGeometry().setFromPoints(arcPts(H, 0, Math.PI * 2, 96));
const nearGeo = new THREE.BufferGeometry().setFromPoints(arcPts(-H, -Math.PI / 2, Math.PI / 2, 48));
const farGeo = new THREE.BufferGeometry().setFromPoints(arcPts(-H, Math.PI / 2, Math.PI * 1.5, 48));
const discGeo = new THREE.CircleGeometry(1, 64);
const ringGeo = (() => {
  const p = [];
  for (let i = 0; i <= 64; i++) { const t = i / 64 * Math.PI * 2; p.push(new THREE.Vector3(Math.cos(t), Math.sin(t), 0)); }
  return new THREE.BufferGeometry().setFromPoints(p);
})();

/* ── analytic conic ─────────────────────────────────────────────────────────
   Plane: unit normal n = (0, cosβ, sinβ), foot P = D(β)·n. In-plane basis
   u = (0,−sinβ, cosβ), v = (1,0,0):   X(a,b) = (b, D cosβ − a sinβ, D sinβ + a cosβ)
   Substituted into the cone x² + z² = K² y² this gives A a² + B a + C + b² = 0.
   The distance D is auto-shrunk so a closed cut always fits inside the drawn cone. */
function baseD(beta) { return 0.45 + 1.10 * Math.exp(-beta / 22); }
function planeD(beta) {
  const br = THREE.MathUtils.degToRad(beta), s = Math.sin(br), c = Math.cos(br);
  let D = baseD(beta);
  const A = c * c - K * K * s * s;
  if (A > 1e-4 && s > 1e-6) {
    const B1 = 2 * s * c * (1 + K * K), C1 = s * s - K * K * c * c;
    const a0 = -B1 / (2 * A), M1 = B1 * B1 / (4 * A) - C1;
    if (M1 > 0) {
      const semi = Math.sqrt(M1 / A), lo = a0 - semi, hi = a0 + semi;
      const d1 = c - lo * s; if (d1 > 1e-6) D = Math.min(D, FIT_MARGIN * H / d1);
      const d2 = hi * s - c; if (d2 > 1e-6) D = Math.min(D, FIT_MARGIN * H / d2);
    }
  }
  return D;
}
function coeffs(beta) {
  const br = THREE.MathUtils.degToRad(beta), s = Math.sin(br), c = Math.cos(br), D = planeD(beta);
  return { A: c * c - K * K * s * s, B: 2 * D * s * c * (1 + K * K), C: D * D * (s * s - K * K * c * c), s, c, D };
}
function effBeta(b) { return Math.abs(b - BETA_PAR) < 0.6 ? BETA_PAR : b; }
function conicName(b) {
  b = effBeta(b);
  if (b < 0.5) return 'Circle';
  if (b === BETA_PAR) return 'Parabola';
  return b < BETA_PAR ? 'Ellipse' : 'Hyperbola';
}
function sliceName(b) {
  const n = conicName(b);
  return n === 'Circle' ? 'Horizontal Slice' : n === 'Ellipse' ? 'Diagonal Slice'
    : n === 'Parabola' ? 'Vertical Slice' : 'Deep Vertical Slice';
}

const PAR_EPS = 1e-6;
function branchesFor(beta) {
  const { A, B, C, s, c, D } = coeffs(beta);
  const f = a => -(A * a * a + B * a + C);
  let aLo = -60, aHi = 60;
  if (s > 1e-6) { aLo = (D * c - H) / s; aHi = (D * c + H) / s; }
  const ivs = [];
  if (Math.abs(A) < PAR_EPS) {
    if (Math.abs(B) > 1e-9) {
      const r = -C / B;
      if (B > 0) ivs.push([aLo, r]); else ivs.push([r, aHi]);
    }
  } else {
    const Dq = B * B - 4 * A * C;
    if (Dq <= 0) { if (A < 0) ivs.push([aLo, aHi]); }
    else {
      const sq = Math.sqrt(Dq);
      let r1 = (-B - sq) / (2 * A), r2 = (-B + sq) / (2 * A);
      if (r1 > r2) { const t = r1; r1 = r2; r2 = t; }
      if (A > 0) ivs.push([r1, r2]);
      else { ivs.push([aLo, r1]); ivs.push([r2, aHi]); }
    }
  }
  const out = [];
  for (const iv of ivs) {
    const p = Math.max(iv[0], aLo), q = Math.min(iv[1], aHi);
    if (!(q - p > 1e-4)) continue;
    const n = 150, up = [], lo = [];
    for (let i = 0; i <= n; i++) {
      const a = p + (q - p) * i / n;
      const b = Math.sqrt(Math.max(0, f(a)));
      up.push([a, b]); lo.push([a, -b]);
    }
    const revLo = lo.slice().reverse();
    const openP = f(p) > 1e-4, openQ = f(q) > 1e-4;
    if (!openP && !openQ) out.push({ pts: up.concat(revLo.slice(1, -1)), closed: true });
    else if (openP && !openQ) out.push({ pts: lo.concat(up.slice().reverse().slice(1)), closed: false });
    else if (!openP && openQ) out.push({ pts: revLo.concat(up.slice(1)), closed: false });
    else { out.push({ pts: up, closed: false }); out.push({ pts: lo, closed: false }); }
  }
  return out;
}

/* ── drawing helpers ────────────────────────────────────────────────────── */
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i]; g.remove(o); o.geometry?.dispose?.();
  }
}
function addTube(g, pts3, closed, rad) {
  const clean = [];
  for (const p of pts3) if (!clean.length || clean[clean.length - 1].distanceTo(p) > 1e-5) clean.push(p);
  if (clean.length < 4) return;
  const curve = new THREE.CatmullRomCurve3(clean, closed, 'centripetal');
  const geo = new THREE.TubeGeometry(curve, Math.min(260, clean.length * 2), rad, 7, closed);
  g.add(new THREE.Mesh(geo, redMat));
}
function addArrow(g, tip, dir) {
  const dd = dir.clone().normalize();
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.14, 12), redMat);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
  m.position.copy(tip).addScaledVector(dd, 0.06);
  g.add(m);
}

/* ── panel factory (one double cone + its slice + its flattened inset) ──── */
const azGroups = [];
function makePanel(xOffset, opts = {}) {
  const flip = opts.flip === -1 ? -1 : 1;
  const g = new THREE.Group(); g.position.x = xOffset;
  const up = new THREE.Mesh(upG, coneMat), dn = new THREE.Mesh(dnG, coneMat);
  g.add(up, dn);
  registerInteractive(up, {
    title: 'Upper nappe', tooltip: 'Upper nappe of the double cone',
    body: 'Rim radius 1.2, height 2.2, so the half-angle from the axis is α = atan(1.2/2.2) ≈ 28.6°. Every conic section is the trace a flat plane leaves on this surface.'
  });
  registerInteractive(dn, {
    title: 'Lower nappe', tooltip: 'Lower nappe',
    body: 'The mirrored cone sharing the apex. A plane steeper than 90° − α ≈ 61.4° reaches this nappe as well — that is exactly why a hyperbola has two branches.'
  });

  const az = new THREE.Group(); g.add(az); azGroups.push(az);
  g.add(new THREE.LineLoop(topRimGeo, navyMat));
  az.add(new THREE.Line(nearGeo, navyMat));
  const fh = new THREE.Line(farGeo, dashMat); fh.computeLineDistances(); az.add(fh);
  [[H, R], [H, -R], [-H, R], [-H, -R]].forEach(([y, z]) => {
    az.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, y, z)]), navyMat));
  });

  const panel = { group: g, flip, curveG: null, flatG: null, plane: null, ring: null, angleG: null };

  if (opts.withPlane) {
    const plane = new THREE.Mesh(discGeo, planeMat);
    const ring = new THREE.LineLoop(ringGeo, ringMat);
    g.add(plane, ring);
    panel.plane = plane; panel.ring = ring;
    registerInteractive(plane, {
      title: 'Cutting plane', tooltip: 'The slicing plane',
      body: 'Only the part of the plane near the cut is drawn. Its tilt β is measured from horizontal: β = 0 → circle · 0 < β < 61.4° → ellipse · β = 61.4° (parallel to a slant line) → parabola · β > 61.4° → hyperbola.'
    });
    const angleG = new THREE.Group(); g.add(angleG); panel.angleG = angleG;
  }

  const curveG = new THREE.Group(); g.add(curveG); panel.curveG = curveG;
  const flatG = new THREE.Group(); flatG.position.y = FLAT_Y; g.add(flatG); panel.flatG = flatG;
  registerInteractive(curveG, {
    title: 'Intersection curve', tooltip: 'Where the plane meets the cone',
    body: 'Substituting the plane parameterisation into x² + z² = (r/h)² y² gives A a² + B a + C + b² = 0 — a genuine conic written in the plane’s own coordinates.'
  });
  registerInteractive(flatG, {
    title: 'The cut, laid flat', tooltip: 'Same curve seen face-on, true shape',
    body: 'The identical red curve viewed perpendicular to the cutting plane, drawn with its true width-to-height ratio — so a slanted cut is visibly flatter than the circle.'
  });
  return panel;
}

function buildCurve(panel, beta, tubeR) {
  clearGroup(panel.curveG);
  const { s, c, D } = coeffs(beta), fl = panel.flip;
  const to3 = (a, b) => new THREE.Vector3(b, fl * (D * c - a * s), D * s + a * c);
  for (const br of branchesFor(beta)) {
    const pts = br.pts.map(p => to3(p[0], p[1]));
    addTube(panel.curveG, pts, br.closed, tubeR);
    if (!br.closed && pts.length > 3) {
      addArrow(panel.curveG, pts[0], pts[0].clone().sub(pts[2]));
      const L = pts.length - 1;
      addArrow(panel.curveG, pts[L], pts[L].clone().sub(pts[L - 2]));
    }
  }
}

function buildFlat(panel, beta, maxW, maxH, tubeR) {
  const g = panel.flatG;
  clearGroup(g);
  const brs = branchesFor(beta);
  if (!brs.length) return;
  const closedKind = brs.every(b => b.closed);
  let aSum = 0, aN = 0;
  for (const br of brs) for (const p of br.pts) { aSum += p[0]; aN++; }
  const aC = aSum / aN;
  // closed cuts: a → horizontal, b → vertical · open cuts: rotate so the vertex sits at the bottom
  const map = closedKind ? (p) => [p[0] - aC, p[1]] : (p) => [p[1], -(p[0] - aC)];
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  const mapped = brs.map(br => {
    const m = br.pts.map(map);
    for (const q of m) {
      minX = Math.min(minX, q[0]); maxX = Math.max(maxX, q[0]);
      minY = Math.min(minY, q[1]); maxY = Math.max(maxY, q[1]);
    }
    return { m, closed: br.closed };
  });
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  const w = Math.max(maxX - minX, 1e-3), h = Math.max(maxY - minY, 1e-3);
  const sc = Math.min(maxW / w, maxH / h, 2.4);      // UNIFORM: true aspect ratio preserved
  for (const { m, closed } of mapped) {
    const pts = m.map(q => new THREE.Vector3((q[0] - cx) * sc, (q[1] - cy) * sc, 0));
    addTube(g, pts, closed, tubeR);
  }
}

/* ── cutting disc + β annotation (single view only) ─────────────────────── */
function placePlane(panel, beta) {
  if (!panel.plane) return;
  const { s, c, D } = coeffs(beta);
  const n = new THREE.Vector3(0, c, s);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), n);
  let rad = 0.55;
  for (const br of branchesFor(beta)) for (const p of br.pts) rad = Math.max(rad, Math.hypot(p[0], p[1]));
  rad = Math.min(rad + 0.22, 1.85);
  const pos = new THREE.Vector3(0, D * c, D * s);
  [panel.plane, panel.ring].forEach(o => { o.quaternion.copy(q); o.position.copy(pos); o.scale.set(rad, rad, 1); });
}

function buildAngle(panel, beta) {
  if (!panel.angleG) return null;
  clearGroup(panel.angleG);
  if (beta < 4) return null;
  const { s, c, D } = coeffs(beta);
  const F = new THREE.Vector3(0, D * c, D * s);
  const rad = 0.52;
  const mk = (v, L) => panel.angleG.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([F.clone(), F.clone().addScaledVector(v, L)]), thinMat));
  mk(new THREE.Vector3(0, 0, 1), rad * 1.4);
  mk(new THREE.Vector3(0, -s, c), rad * 1.4);
  const br = THREE.MathUtils.degToRad(beta), pts = [];
  for (let i = 0; i <= 28; i++) {
    const t = br * i / 28;
    pts.push(F.clone().add(new THREE.Vector3(0, -Math.sin(t), Math.cos(t)).multiplyScalar(rad)));
  }
  panel.angleG.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), thinMat));
  const hb = br / 2;
  return F.clone().add(new THREE.Vector3(0, -Math.sin(hb), Math.cos(hb)).multiplyScalar(rad + 0.26));
}

/* ── roots: single view and the four-panel comparison ───────────────────── */
const singleRoot = new THREE.Group();
const quadRoot = new THREE.Group();
const single = makePanel(0, { withPlane: true });
singleRoot.add(single.group);

const QUAD = [
  { x: -4.5, beta: 50, title: 'Diagonal Slice', flip: 1 },
  { x: -1.5, beta: 0, title: 'Horizontal Slice', flip: 1 },
  { x: 1.5, beta: 85, title: 'Deep Vertical Slice', flip: 1 },
  { x: 4.5, beta: BETA_PAR, title: 'Vertical Slice', flip: -1 }
];
const quadLabels = [];
QUAD.forEach(q => {
  const p = makePanel(q.x, { flip: q.flip });
  buildCurve(p, q.beta, 0.016);
  buildFlat(p, q.beta, 2.15, 1.15, 0.019);
  quadRoot.add(p.group);
  q.panel = p;
});
scene.add(quadRoot);

/* ── labels ─────────────────────────────────────────────────────────────── */
const lblTitle = addLabel('Diagonal Slice', new THREE.Vector3(0, TITLE_Y, 0), { bold: true, fontSize: '18px' });
const lblName = addLabel('Ellipse', new THREE.Vector3(0, NAME_Y, 0), { bold: true, fontSize: '17px' });
const lblBeta = addLabel('&beta;', new THREE.Vector3(0, 0, 0), { fontSize: '13px', color: '#555' });

QUAD.forEach(q => {
  const t = addLabel(q.title, new THREE.Vector3(q.x, TITLE_Y, 0), { bold: true, fontSize: '15px' });
  const n = addLabel(conicName(q.beta), new THREE.Vector3(q.x, NAME_Y, 0), { bold: true, fontSize: '15px' });
  quadLabels.push(t, n);
});
function setLblVis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── state + UI refs ────────────────────────────────────────────────────── */
const state = { beta: 50, mode: 'quad', showPlane: true };
const slider = document.getElementById('planeAngle');
const angVal = document.getElementById('angVal');
const readout = document.getElementById('readout');
const chkPlane = document.getElementById('showPlane');
const btnOne = document.getElementById('modeOne');
const btnAll = document.getElementById('modeAll');
const conicBtns = {
  Ellipse: document.getElementById('cEll'), Circle: document.getElementById('cCir'),
  Hyperbola: document.getElementById('cHyp'), Parabola: document.getElementById('cPar')
};

function frameCamera() {
  setCameraView({
    projection: 'orthographic', azimuthDeg: 90, elevationDeg: 12,
    heightFraction: state.mode === 'single' ? 0.78 : 0.92
  });
  controls.minPolarAngle = THREE.MathUtils.degToRad(20);
  controls.maxPolarAngle = THREE.MathUtils.degToRad(160);
}

function update(reframe) {
  const b = effBeta(state.beta);
  angVal.textContent = state.beta.toFixed(0);
  slider.value = String(Math.round(state.beta));
  const name = conicName(state.beta);
  Object.entries(conicBtns).forEach(([k, el]) => el.classList.toggle('active', k === name && state.mode === 'single'));
  btnOne.classList.toggle('active', state.mode === 'single');
  btnAll.classList.toggle('active', state.mode === 'quad');

  placePlane(single, b);
  const showP = state.showPlane && state.mode === 'single';
  single.plane.visible = showP; single.ring.visible = showP;
  const bp = buildAngle(single, b);
  single.angleG.visible = showP;
  if (bp && showP) { lblBeta.pos.copy(bp); setLblVis(lblBeta, true); } else setLblVis(lblBeta, false);

  buildCurve(single, b, 0.016);
  buildFlat(single, b, 2.5, 1.35, 0.019);

  const cmp = (name === 'Parabola') ? '=' : (b < BETA_PAR ? '&lt;' : '&gt;');
  readout.innerHTML = '&beta; = <b>' + state.beta.toFixed(0) + '&deg;</b> ' + cmp
    + ' 90&deg; &minus; &alpha; = 61.4&deg; &rarr; <b style="color:#c0271f">' + name + '</b><br>'
    + (name === 'Circle' ? 'Cut perpendicular to the axis — every point of the cut is the same distance from it.'
      : name === 'Ellipse' ? 'Plane less steep than the cone’s side, so the cut closes into an oval; the steeper the tilt, the flatter the ellipse.'
        : name === 'Parabola' ? 'Plane exactly parallel to a slant line — the cut can never close.'
          : 'Plane steeper than the side, so it meets <i>both</i> nappes: two branches.');

  lblTitle.div.innerHTML = sliceName(state.beta);
  lblName.div.innerHTML = name;
  if (reframe) frameCamera();
}

function applyLabelVisibility() {
  const one = state.mode === 'single';
  setLblVis(lblTitle, one); setLblVis(lblName, one);
  if (!one) setLblVis(lblBeta, false);
  quadLabels.forEach(l => setLblVis(l, !one));
}

function setMode(m) {
  if (state.mode === m) return;
  state.mode = m;
  if (m === 'quad') { scene.remove(singleRoot); scene.add(quadRoot); }
  else { scene.remove(quadRoot); scene.add(singleRoot); }
  applyLabelVisibility();
  update(true);
}

/* ── controls wiring ────────────────────────────────────────────────────── */
let tweenId = 0;
function tweenBeta(target, ms, done) {
  const id = ++tweenId, from = state.beta, t0 = performance.now();
  (function step() {
    if (id !== tweenId) return;
    const t = Math.min(1, (performance.now() - t0) / ms);
    const e = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    state.beta = from + (target - from) * e;
    update(false);
    if (t < 1) requestAnimationFrame(step); else if (done) done();
  })();
}

let playing = false;
function stopPlay() { playing = false; document.getElementById('playDemo').textContent = '▶ Play'; }

slider.addEventListener('input', () => {
  tweenId++;
  if (state.mode !== 'single') setMode('single');
  state.beta = parseFloat(slider.value);
  update(false);
});
btnOne.addEventListener('click', () => setMode('single'));
btnAll.addEventListener('click', () => { stopPlay(); setMode('quad'); });
chkPlane.addEventListener('change', () => { state.showPlane = chkPlane.checked; update(false); });

const presets = { Ellipse: 50, Circle: 0, Hyperbola: 85, Parabola: BETA_PAR };
Object.entries(conicBtns).forEach(([k, el]) => el.addEventListener('click', () => {
  if (state.mode !== 'single') setMode('single');
  tweenBeta(presets[k], 600);
}));

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'The figure: four slices', n: 'Four identical double cones, each cut by a plane at a different tilt. The red curve on top is the intersection; underneath, the same cut is drawn flat and true to shape — ellipse, circle, hyperbola, parabola.', b: 50, m: 'quad' },
  { t: 'Diagonal Slice → Ellipse', n: 'A plane tilted 50° from horizontal cuts clean through the upper nappe only. The red intersection closes into a tilted oval; flattened below the cone it is a distinctly elongated ellipse.', b: 50, m: 'single' },
  { t: 'Horizontal Slice → Circle', n: 'Level the plane to 0°. The cut is perpendicular to the axis, so every point of the red curve is the same distance from it: a circle — the special ellipse with equal axes.', b: 0, m: 'single' },
  { t: 'Vertical Slice → Parabola', n: 'At 61.4° the plane is exactly parallel to a slant line of the cone. The cut can no longer close — one open red arc runs out to the rim, and flattened it is a parabola.', b: BETA_PAR, m: 'single' },
  { t: 'Deep Vertical Slice → Hyperbola', n: 'Past 61.4° — here 85°, nearly vertical — the plane is steeper than the cone’s side, so it meets both nappes. Two opposing red branches appear: a hyperbola.', b: 85, m: 'single' },
  { t: 'Back to all four', n: 'Compare the row again: the tilt β of one flat plane, and nothing else, decides which conic you get.', b: 50, m: 'quad' }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(i, after) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.t;
  stepText.textContent = s.n;
  setMode(s.m);
  if (s.m === 'single') tweenBeta(s.b, 650, after);
  else { state.beta = s.b; update(false); if (after) setTimeout(after, 700); }
}
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  playing = !playing;
  document.getElementById('playDemo').textContent = playing ? '❚❚ Pause' : '▶ Play';
  if (playing) run();
});
function run() {
  if (!playing) return;
  goToStep(stepIdx + 1, () => setTimeout(() => { if (playing) run(); }, 2000));
}

/* ── azimuth tracking for dashed rim + silhouette lines ─────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  const dx = camera.position.x - controls.target.x;
  const dz = camera.position.z - controls.target.z;
  if (dx * dx + dz * dz > 1e-8) {
    const r = Math.atan2(-dz, dx);
    for (const g of azGroups) g.rotation.y = r;
  }
})();

/* ── go ─────────────────────────────────────────────────────────────────── */
update(false);
applyLabelVisibility();
frameCamera();
document.getElementById('btnReset').style.display = '';
stepTitle.textContent = '1/' + steps.length + '  ' + steps[0].t;
stepText.textContent = steps[0].n;
